window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[90]={"id":"090","numero":90,"titre":"Pathologies des glandes salivaires","objectifs":[{"id":"90-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la clinique des lithiases submandibulaire et parotidienne","contenu":"<p>La <span class=\"kw-def\">lithiase salivaire</span> = présence de <span class=\"kw-clinique\">calculs de sels de calcium</span> au sein de la glande et/ou de son canal excréteur. Localisations&nbsp;: <span class=\"kw-chiffre\">85% submandibulaire</span> &gt; <span class=\"kw-chiffre\">15% parotidienne (5× moins fréquente)</span> &gt; sublinguale et accessoires exceptionnelles.</p>\n\n      <table >\n        <thead>\n          <tr><th>Caractéristique</th><th>Lithiase submandibulaire</th><th>Lithiase parotidienne</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Conduit excréteur</strong></td>\n            <td>Canal de Wharton — <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-chiffre\">&lt; 4 mm</span></td>\n            <td>Canal de Sténon — <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-chiffre\">&lt; 2 mm</span></td>\n          </tr>\n          <tr>\n            <td><strong>Topographie des signes</strong></td>\n            <td>Région submandibulaire (sous la mandibule) ; calcul palpable le long du Wharton</td>\n            <td>Loge parotidienne (en arrière du ramus mandibulaire, sous l'oreille externe)</td>\n          </tr>\n          <tr>\n            <td><strong>Complications dominantes</strong></td>\n            <td><span class=\"kw-clinique\">Complications mécaniques</span> au 1ᵉʳ plan (hernie + colique salivaires rythmées par <span class=\"kw-clinique\">les</span> repas)</td>\n            <td><span class=\"kw-clinique\">Complications infectieuses</span> plus fréquentes (conduit plus étroit)</td>\n          </tr>\n          <tr>\n            <td><strong>Sialodochite</strong></td>\n            <td><strong>Whartonite</strong> : <span class=\"kw-clinique\">fièvre</span> élevée + douleur vive irradiant vers l'oreille + <span class=\"kw-clinique\">dysphagie</span> + hypersialorrhée ; <span class=\"kw-clinique\">issue de pus à l'ostium près du frein</span></td>\n            <td><strong>Sténonite</strong> : inflammation jugale sur le trajet du conduit + issue de pus à l'ostium</td>\n          </tr>\n          <tr>\n            <td><strong>Périsialodochite</strong></td>\n            <td><strong><span class=\"kw-clinique\">Abcès</span> du plancher (périwhartonite)</strong> : signes généraux + <span class=\"kw-clinique\">tuméfaction</span> du plancher buccal + <span class=\"kw-clinique\">dysphagie</span> + odynophagie + <span class=\"kw-alerte\">trismus</span> ± <span class=\"kw-clinique\">otalgie</span></td>\n            <td><strong><span class=\"kw-clinique\">Abcès</span> de la joue</strong> : inflammation de toute la joue</td>\n          </tr>\n          <tr>\n            <td><strong>Sialadénite</strong></td>\n            <td><strong>Submandibulite</strong> : <span class=\"kw-clinique\">fièvre</span><span class=\"kw-chiffre\"> 38–39°C</span> + <span class=\"kw-clinique\">dysphagie</span> + <span class=\"kw-clinique\">otalgie</span> ± issue de pus ; risque de <span class=\"kw-alerte\">fistulisation cervicale</span></td>\n            <td><strong>Parotidite</strong> : inflammation/douleur en regard de la loge parotidienne</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Examen clinique salivaire systématique.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Inspection exobuccale</span> : gonflement de la glande</li>\n          <li><span class=\"kw-clinique\">Inspection endobuccale</span> : calcul visible par transparence sous la muqueuse, rougeur de la crête salivaire, issue de pus à l'ostium turgescent</li>\n          <li><span class=\"kw-clinique\">Palpation bidigitale</span> : 1 doigt endobuccal + 1 doigt cervical, de l'arrière vers l'avant, recherche le calcul</li>\n        </ul>\n      </div>","frequence":6,"liens":[{"href":"https://radiopaedia.org/articles/sialolithiasis","label":"Radiopaedia : Sialolithiasis"}]},{"id":"90-2","rang":"A","rubrique":"Définition","titre":"Connaître les trois étiologies principales des pathologies des glandes salivaires","contenu":"<p>Devant une <span class=\"kw-clinique\">tuméfaction salivaire</span>, le raisonnement diagnostique repose sur 2 questions ouvrant <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rands cadres&nbsp;: <strong>inflammation ?</strong> (oui = sialadénite / non = sialose ou tumeur), puis <strong>bilatéralité ?</strong> (oriente vers une cause générale).</p>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Définition</th><th>Mécanisme dominant</th><th>Signe clinique pivot</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sialadénite (sialite)</strong></td>\n            <td><span class=\"kw-def\">Inflammation ou infection aiguë essentiellement parenchymateuse</span> d'une glande salivaire</td>\n            <td>Soit <span class=\"kw-clinique\">obstructive</span> (canal bouché, ex. lithiase) — soit <span class=\"kw-clinique\">non obstructive</span> (voie générale, ex. virus)</td>\n            <td><span class=\"kw-clinique\">Tuméfaction inflammatoire douloureuse</span> ± <span class=\"kw-clinique\">fièvre</span> ± issue de pus à l'ostium</td>\n          </tr>\n          <tr>\n            <td><strong>Sialadénose (sialose)</strong></td>\n            <td><span class=\"kw-def\">Hypertrophie globale chronique</span>, le plus souvent <span class=\"kw-def\">bilatérale</span>, sans signe <span class=\"kw-etio\">inflammatoire</span></td>\n            <td>Pathologie générale <span class=\"kw-clinique\">immunologique</span>, <span class=\"kw-clinique\">nutritionnelle</span> ou <span class=\"kw-clinique\">endocrinienne</span></td>\n            <td><span class=\"kw-clinique\">Parotidomégalie bilatérale indolore</span>, sans douleur, sans infection, sans signe <span class=\"kw-etio\">inflammatoire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Tumeur</strong></td>\n            <td><span class=\"kw-def\">Tuméfaction nodulaire</span> isolée, le plus souvent <span class=\"kw-def\">parotidienne</span>, le plus souvent <span class=\"kw-def\">bénigne</span></td>\n            <td>Adénome pléomorphe ++ ; Warthin ; carcinomes muco-épidermoïde et adénoïde kystique pour <span class=\"kw-clinique\">les</span> malignes</td>\n            <td><span class=\"kw-clinique\">Nodule unilatéral</span> d'allure non <span class=\"kw-etio\">inflammatoire</span>, indolore le plus souvent (toute douleur = cancer JPDC)</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"90-3","rang":"A","rubrique":"Diagnostic","titre":"Savoir différencier les trois types de pathologie des glandes salivaires","contenu":"<p>Le raisonnement Rang A enchaîne 2 questions — <strong>inflammation&nbsp;?</strong> puis <strong>latéralité&nbsp;?</strong> — qui isolent <span class=\"kw-clinique\">les</span> 3 cadres. Garde-fou&nbsp;: <span class=\"kw-alerte\">toute douleur sur une tuméfaction non inflammatoire = cancer jusqu'à preuve du contraire</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Sialadénite (sialite)</th><th>Sialose (sialadénose)</th><th>Tumeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Inflammation</strong></td>\n            <td><span class=\"kw-clinique\">Oui</span></td>\n            <td>Non</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Latéralité</strong></td>\n            <td>Uni- ou bilatérale</td>\n            <td><span class=\"kw-clinique\">Bilatérale ++</span></td>\n            <td><span class=\"kw-clinique\">Unilatérale ++</span></td>\n          </tr>\n          <tr>\n            <td><strong>Douleur</strong></td>\n            <td><span class=\"kw-clinique\">Oui</span> ± <span class=\"kw-clinique\">fièvre</span></td>\n            <td>Non (sensation de <span class=\"kw-clinique\">pesanteur</span>)</td>\n            <td>Non — <span class=\"kw-alerte\">toute douleur = cancer JPDC</span></td>\n          </tr>\n          <tr>\n            <td><strong>Type de <span class=\"kw-clinique\">tuméfaction</span></strong></td>\n            <td>Glande inflammée ± <span class=\"kw-clinique\">pus à l'ostium</span></td>\n            <td>Parotidomégalie globale chronique</td>\n            <td><span class=\"kw-clinique\">Nodule isolé</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Lithiase, virus, bactérie</td>\n            <td>Maladie générale (immuno / nutri / endoc)</td>\n            <td>Adulte <span class=\"kw-chiffre\">30–60 ans</span>, parotide ++</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Arbre d'orientation simplifié (issu de obj-1).</strong>\n        <ul>\n          <li>Inflammation présente → <strong>Sialadénite</strong> (rechercher lithiase + <span class=\"kw-clinique\">porte d'entrée</span> canalaire / hématogène / <span class=\"kw-etio\">virale</span>)</li>\n          <li>Pas d'inflammation, <strong>unilatérale</strong> → <strong>Tumeur</strong> (parotide ++) ou Warthin si bilatéralité<span class=\"kw-chiffre\"> 10%</span></li>\n          <li>Pas d'inflammation, <strong>bilatérale</strong> → <strong>Sialose</strong> (chercher Gougerot, <span class=\"kw-chiffre\">IgG</span>4, <span class=\"kw-clinique\">sarcoïdose</span>, cause endocrinienne/nutritionnelle)</li>\n        </ul>\n      </div>","frequence":0},{"id":"90-4","rang":"B","rubrique":"Examens complémentaires","titre":"Indication des examens d’imagerie devant une pathologie des glandes salivaires","contenu":"<p>La <strong>stratégie d'imagerie</strong> dépend du contexte clinique&nbsp;: <span class=\"kw-clinique\">recherche de lithiase</span> (<span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-imagerie\">TDM</span> ± sialendoscopie) <span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">caractérisation d'une tumeur</span> (<span class=\"kw-imagerie\">IRM</span> impérative).</p>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Place dans la lithiase</th><th>Place dans la tumeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Panoramique dentaire</span></strong></td>\n            <td><span class=\"kw-clinique\">Systématique</span> — visualise <span class=\"kw-clinique\">les</span> gros calculs en regard de l'angle mandibulaire et <strong>élimine une pathologie dentaire</strong></td>\n            <td>Non indiqué</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td>\n            <td>1ʳᵉ intention — visualise <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">calculs ≥ 2 mm</span>, opaques ou radiotransparents (hyperéchogène + cône d'ombre postérieur) ; opérateur-dépendante, FN sur calculs antérieurs</td>\n            <td>Examen de débrouillage ; précise la topographie intra/extra-glandulaire ; guide la cytoponction ; <strong>ne dispense pas de l'<span class=\"kw-imagerie\">IRM</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> (cervical, non injecté ou cone-beam)</strong></td>\n            <td>Très grande sensibilité pour <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">calculs radio-opaques</span> ; mesure les diamètres + grande valeur localisatrice ; clichés <em>low dose</em> / cone-beam pour limiter l'<span class=\"kw-clinique\">irradiation</span></td>\n            <td>Si doute diagnostique (<span class=\"kw-clinique\">adénopathie</span> extraparotidienne, <span class=\"kw-clinique\">abcès</span>, kyste sébacé) ; sans puis avec PDC</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> (avec gado et perfusion-<span class=\"kw-imagerie\">diffusion</span>)</strong></td>\n            <td>Coûteuse, <strong>moins sensible que la <span class=\"kw-imagerie\">TDM</span></strong>, pas d'éléments supplémentaires ; <em>peut se discuter chez l'enfant (non irradiante)</em></td>\n            <td><span class=\"kw-imagerie\">Examen de choix des tumeurs salivaires</span> — détecte <span class=\"kw-clinique\">les</span> petites tumeurs, localise le nerf facial, détecte les extensions périneurales, élimine les masses extraparotidiennes, oriente le diagnostic histopronostique via les séquences de perfusion-<span class=\"kw-imagerie\">diffusion</span></td>\n          </tr>\n          <tr>\n            <td><strong>Sialo-<span class=\"kw-imagerie\">IRM</span></strong></td>\n            <td>Peut montrer une <span class=\"kw-imagerie\">sténose canalaire</span> (4 stades : diaphragmatique, légère/modérée, en chapelet de saucisse, totale)</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Sialendoscopie</strong></td>\n            <td>Sous anesthésie locale — diagnostique <strong>ET thérapeutique</strong> (visualisation + retrait du calcul en un temps) ; CI en surinfection</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Scintigraphie</span></strong></td>\n            <td>—</td>\n            <td>Peu utilisée ; seul le <span class=\"kw-clinique\">cystadénolymphome</span> présente une <span class=\"kw-imagerie\">hyperfixation</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TEP</span>-<span class=\"kw-imagerie\">scanner</span></strong></td>\n            <td>—</td>\n            <td>Non recommandé en routine ; bonne Se pour <span class=\"kw-clinique\">les</span> métastases</td>\n          </tr>\n          <tr>\n            <td><strong>Cytoponction à l'aiguille fine (FNAC)</strong></td>\n            <td>—</td>\n            <td>Échoguidée, <strong>après l'<span class=\"kw-imagerie\">IRM</span></strong> ; Se/Sp <span class=\"kw-chiffre\">90%</span> ; <strong>ne donne pas le diagnostic histologique</strong> ; couplée à l'<span class=\"kw-imagerie\">IRM</span> = diagnostic dans <span class=\"kw-chiffre\">90%</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 0.8em 0 0.3em; color: var(--ink);\">Aspect <span class=\"kw-imagerie\">IRM</span> des principales tumeurs parotidiennes (lésions &gt;<span class=\"kw-chiffre\"> 1 cm</span>)</h4>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Adénome pléomorphe</th><th>Tumeur de Warthin</th><th><span class=\"kw-clinique\">Carcinome</span> muco-épidermoïde</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>T1</strong></td><td>Non spécifique (isosignal cerveau/muscle)</td><td>HyperT1 selon ORL / Iso-HypoT1</td><td>HypoT1 (sauf lymphome iso)</td></tr>\n          <tr><td><strong>T2</strong></td><td><span class=\"kw-imagerie\">HyperT2</span> (comme <span class=\"kw-bio\">LCS</span>), homogène, bien limité, capsule fine en hyposignal</td><td>Iso/HypoT2</td><td>Iso/Hypo « <span class=\"kw-imagerie\">evil gray</span> »</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Diffusion</span> (ADC)</strong></td><td>Sans restriction (ADC &gt; 1,4)</td><td>Restriction forte (ADC ≈ 0,6)</td><td>Restriction intermédiaire (ADC 0,6 à 1,2)</td></tr>\n          <tr><td><strong>Perfusion (DCE)</strong></td><td>Rehaussement <span class=\"kw-imagerie\">progressif</span> sur <span class=\"kw-chiffre\">5 min</span> (pic &gt; 120 s)</td><td>Rehaussement <span class=\"kw-imagerie\">explosif</span> (pic <span class=\"kw-chiffre\">≤ 120</span> s) + <strong>lavage rapide</strong> (washout &gt;<span class=\"kw-chiffre\"> 30%</span>)</td><td>Rehaussement rapide + <strong>lavage lent</strong> (washout &lt;<span class=\"kw-chiffre\"> 30%</span>)</td></tr>\n          <tr><td><strong>Contours / Multifocalité</strong></td><td>Festonnés, unifocal</td><td>Réguliers, multifocal, bilatéralité<span class=\"kw-chiffre\"> 10%</span></td><td>Irréguliers, <span class=\"kw-ttt\">infiltration</span>, multifocalité surtout si lymphome</td></tr>\n        </tbody>\n      </table>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/salivary-glands","label":"Radiopaedia : Salivary glands (anatomie)"},{"href":"https://radiopaedia.org/articles/parotid-gland","label":"Radiopaedia : Parotid gland"},{"href":"https://radiopaedia.org/articles/submandibular-gland","label":"Radiopaedia : Submandibular gland"}]},{"id":"90-5","rang":"A","rubrique":"Contenu multimédia","titre":"Iconographie clinique d’un exemple typique de tuméfaction parotidienne","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif à compléter (contenu multimédia)</strong> — squelette ajouté lors de l’alignement sur la trame officielle EDN (25/05/2026). Iconographie clinique à déposer dans <code>assets/images/90/</code> (photo cliché de <span class=\"kw-clinique\">tuméfaction</span> parotidienne typique).\n      </div>","frequence":0},{"id":"90-6","rang":"B","rubrique":"Contenu multimédia","titre":"Iconographie clinique d’un exemple typique de sialite","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif à compléter (contenu multimédia)</strong> — squelette ajouté lors de l’alignement sur la trame officielle EDN (25/05/2026). Iconographie clinique à déposer dans <code>assets/images/90/</code> (photo cliché de sialite typique).\n      </div>","frequence":0},{"id":"90-7","rang":"A","rubrique":"Etiologies","titre":"Savoir les trois causes principales de sialites","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">sialadénites</span> se répartissent en <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>randes familles étiologiques, dont la fréquence relative dépend du <strong><span class=\"kw-def\">terrain</span></strong> et de la <strong>glande</strong> touchée.</p>\n\n      <table >\n        <thead>\n          <tr><th>Famille</th><th>Agent / mécanisme</th><th>Glande de prédilection</th><th>Particularité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"5\"><strong>Virales</strong> (cause générale, souvent bilatérales)</td>\n            <td>Paramyxovirus — <span class=\"kw-clinique\">oreillons</span> ⭐ (le plus classique)</td>\n            <td>Parotide ++</td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> bilatérale qui refoule le lobule ; <span class=\"kw-bio\">amylasémie élevée J6–J10</span> ; complications (orchite, <span class=\"kw-def\">méningite</span>, <span class=\"kw-def\">encéphalite</span>, surdité)</td>\n          </tr>\n          <tr><td><span class=\"kw-etio\">VIH</span></td><td>Parotide</td><td><span class=\"kw-clinique\">Hyperplasie lymphoïde kystique</span></td></tr>\n          <tr><td>Coxsackies, <span class=\"kw-etio\">Grippe</span>, Echovirus</td><td>Parotide</td><td>Épidémies hiver/printemps</td></tr>\n          <tr><td><span class=\"kw-etio\">CMV</span>, EBV, COVID-19</td><td>Parotide</td><td>—</td></tr>\n          <tr><td>—</td><td>—</td><td><strong>Signe négatif clé</strong> : pas d'écoulement purulent à l'ostium de Sténon</td></tr>\n          <tr>\n            <td rowspan=\"3\"><strong>Bactériennes</strong> (cause locale, souvent unilatérales)</td>\n            <td>Sialite d'origine <span class=\"kw-clinique\">lithiasique</span> ++</td>\n            <td>Submandibulaire (<span class=\"kw-chiffre\">85%</span>)</td>\n            <td>Voie canalaire ascendante (favorisée par l'obstacle salivaire)</td>\n          </tr>\n          <tr>\n            <td>Infections à <span class=\"kw-clinique\">pyogènes</span> de l'adulte (<span class=\"kw-etio\">staphylocoques</span> dorés, <span class=\"kw-etio\">anaérobies</span>)</td>\n            <td>Parotide ++</td>\n            <td>Patient âgé, hospitalisé en <span class=\"kw-alerte\">réanimation</span>, immunodéprimé, déshydraté ; <span class=\"kw-clinique\">issue de pus à l'ostium</span></td>\n          </tr>\n          <tr>\n            <td>Parotidite récidivante de l'enfant (juvénile)</td>\n            <td>Parotide</td>\n            <td>Étiologie inconnue ; débute à<span class=\"kw-chiffre\"> 4–5 ans</span>, disparaît à l'adolescence ; uni- ou bilatérale ; <span class=\"kw-imagerie\">échographie</span> sans calcul ; <em>passée rang C dans la nouvelle édition</em></td>\n          </tr>\n          <tr>\n            <td><strong>Lithiasiques</strong></td>\n            <td>Calculs de sels de calcium (cf. obj-0)</td>\n            <td>Submandibulaire <span class=\"kw-chiffre\">85%</span> &gt; parotide <span class=\"kw-chiffre\">15%</span></td>\n            <td>Présentation rythmée par <span class=\"kw-clinique\">les</span> repas, complications mécaniques avant infectieuses</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Mnémo <span class=\"kw-def\">terrain</span>.</strong>\n        <ul>\n          <li><strong>Bilatérale</strong> + <strong><span class=\"kw-clinique\">fièvre</span> <span class=\"kw-etio\">virale</span></strong> + <strong>enfant non vacciné</strong> → oreillons</li>\n          <li><strong>Unilatérale</strong> + <strong>pus à l'ostium</strong> + <strong><span class=\"kw-def\">terrain</span> fragile</strong> → sialite <span class=\"kw-etio\">bactérienne</span> à pyogènes</li>\n          <li><strong>Unilatérale</strong> + <strong>épisodes rythmés par <span class=\"kw-clinique\">les</span> repas</strong> + <strong>jet de salive sous la langue</strong> → lithiase submandibulaire ⭐</li>\n          <li><strong>Parotidite récidivante chez l'adulte</strong> → évoquer la <span class=\"kw-alerte\">tuberculose</span></li>\n        </ul>\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/sialadenitis","label":"Radiopaedia : Sialadenitis"},{"href":"https://radiopaedia.org/articles/sjogren-syndrome-1","label":"Radiopaedia : Sjögren syndrome"}]},{"id":"90-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des lithiases submandibulaire et parotidienne","contenu":"<h4 style=\"margin: 0.4em 0 0.3em; color: var(--ink);\">Sialadénite <span class=\"kw-etio\">virale</span> (oreillons)</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Traitement symptomatique</span> : repos, réhydratation, antipyrétique, <span class=\"kw-ttt\">antalgique</span></li>\n        <li><strong>Éviction scolaire <span class=\"kw-chiffre\">15 jours</span></strong></li>\n        <li>Guérison spontanée en <span class=\"kw-chiffre\">8–15 jours</span> ; complications rares (orchite avec stérilité 2ᵃⁱʳᵉ, <span class=\"kw-def\">méningite</span>, <span class=\"kw-def\">encéphalite</span>, surdité)</li>\n      </ul>\n\n      <h4 style=\"margin: 0.6em 0 0.3em; color: var(--ink);\">Sialadénite <span class=\"kw-etio\">bactérienne</span> / lithiasique surinfectée</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Traitement médical pendant ≥ 10 jours</span></li>\n        <li>ATB : <span class=\"kw-ttt\">spiramycine + métronidazole</span></li>\n        <li><span class=\"kw-ttt\">Corticoïdes</span></li>\n        <li><span class=\"kw-ttt\">Antalgiques</span> + <span class=\"kw-ttt\">réhydratation</span></li>\n        <li><strong>Traitement étiologique secondaire</strong> par levée de l'obstruction lithiasique (cf. tableau ci-dessous) pour récupérer la fonction salivaire</li>\n      </ul>\n\n      <h4 style=\"margin: 0.8em 0 0.3em; color: var(--ink);\">Lithiase salivaire — algorithme thérapeutique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Localisation</th><th>Lithiase submandibulaire</th><th>Lithiase parotidienne</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Diamètre</span> du conduit</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 4 mm</span> (Wharton)</td>\n            <td><span class=\"kw-chiffre\">&lt; 2 mm</span> (Sténon)</td>\n          </tr>\n          <tr>\n            <td><strong>1/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> an</span>térieur</strong></td>\n            <td>Taille endobuccale sous anesthésie <span class=\"kw-clinique\">locale</span> (en avant de la 1ʳᵉ molaire, en avant du croisement avec le nerf lingual)</td>\n            <td>Taille endobuccale sous anesthésie <span class=\"kw-clinique\">générale</span> (en avant du bord antérieur du masséter) — AG car risque de migration lithiasique ; <span class=\"kw-alerte\">pas de risque facial à ce niveau</span></td>\n          </tr>\n          <tr>\n            <td><strong>1/3 moyen et postérieur — calcul ≤ taille du canal</strong></td>\n            <td><span class=\"kw-clinique\">Sialendoscopie</span> si &lt;<span class=\"kw-chiffre\"> 4 mm</span> (lithiase mobile)</td>\n            <td><span class=\"kw-clinique\">Sialendoscopie</span> si <span class=\"kw-chiffre\">≤ 2 mm</span></td>\n          </tr>\n          <tr>\n            <td><strong>1/3 moyen et postérieur — calcul &gt; taille du canal</strong></td>\n            <td><span class=\"kw-clinique\">Taille endobuccale</span> par ouverture du canal et retrait du calcul (calcul bloqué)</td>\n            <td>\n              <strong>Fragmentation</strong> (lithotripsie ou <span class=\"kw-ttt\">laser</span>) puis :<br>\n              → sialendoscopie seule si fragmenté ;<br>\n              → abord par voie de lifting si non fragmenté (repérage par transillumination via le sialendoscope, glande parotide conservée)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Sialendoscopie — CI à connaître.</strong> Contre-indiquée en cas de <span class=\"kw-alerte\">surinfection</span> (sialodochite, périsialodochite) ; il faut d'abord drainer l'<span class=\"kw-clinique\">abcès</span> et passer la phase aiguë (ATB) avant de programmer le geste endoscopique. La mise à plat d'un <span class=\"kw-clinique\">abcès</span> permet souvent le retrait concomitant de la lithiase.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Parotidite récidivante de l'enfant — prise en charge spécifique.</strong>\n        <ul>\n          <li><strong>Épisodes aigus</strong> : ATB adaptée + anti-inflammatoires</li>\n          <li><strong>Préventif</strong> : massages quotidiens, <span class=\"kw-clinique\">sialendoscopie</span> (dilatation canalaire, ablation de micropolypes, lavages, instillation locale d'ATB)</li>\n        </ul>\n      </div>","frequence":0},{"id":"90-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge des tumeurs des glandes salivaires","contenu":"<p>La <strong>parotidectomie</strong> est le geste de référence ; le couple <span class=\"kw-clinique\">IRM + cytoponction</span> donne le diagnostic dans <span class=\"kw-chiffre\">90% des cas</span> et oriente le chirurgien en amont. <span class=\"kw-alerte\">Jamais de biopsie</span> (risque de <span class=\"kw-clinique\">lésion</span> du nerf facial et de dissémination — la cytoponction reste sans risque).</p>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Geste</th><th>Conditions / particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tumeur bénigne, lobe superficiel</strong></td>\n            <td><span class=\"kw-clinique\">Parotidectomie partielle / exofaciale / superficielle</span></td>\n            <td>Passer <strong>au large</strong> de la tumeur, respecter le nerf facial ; la tumeur ne doit pas être vue durant l'intervention</td>\n          </tr>\n          <tr>\n            <td><strong>Tumeur bénigne volumineuse / lobe profond</strong></td>\n            <td><span class=\"kw-clinique\">Parotidectomie totale</span></td>\n            <td>Repérage premier du nerf facial</td>\n          </tr>\n          <tr>\n            <td><strong>Tumeur maligne (extemporané)</strong></td>\n            <td><span class=\"kw-clinique\">Parotidectomie totale + curage ganglionnaire homolatéral</span></td>\n            <td>Patient prévenu de la radicalité chirurgicale</td>\n          </tr>\n          <tr>\n            <td><strong>Indications de <span class=\"kw-ttt\">radiothérapie</span> adjuvante</strong></td>\n            <td><span class=\"kw-ttt\">Radiothérapie postopératoire</span></td>\n            <td>Haut <span class=\"kw-def\">grade</span> (carcinomes épidermoïdes, adénoïdes kystiques…), tumeurs malignes avancées, limites chirurgicales positives, <span class=\"kw-bio\">envahissement</span> cutané ou nerveux</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span> simple (sans parotidectomie)</strong></td>\n            <td>Clinico-radiologique</td>\n            <td>Patient en <span class=\"kw-alerte\">très mauvais état général</span> OU <strong>Warthin quasi-certain</strong> avec <span class=\"kw-imagerie\">IRM</span>/cytoponction concordantes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Complications de la parotidectomie à connaître.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Paralysie faciale</span> — <span class=\"kw-chiffre\">20%</span>, transitoire ou définitive (atteinte peropératoire du VII)</li>\n          <li><span class=\"kw-alerte\">Syndrome de Frey</span> — <span class=\"kw-chiffre\">15%</span>, tardif : rougeur + sudation per-prandiale en région massétérine, par mauvaise régénération nerveuse ; traitement par <span class=\"kw-ttt\">injections de toxine botulique</span></li>\n          <li><span class=\"kw-clinique\">Cicatrice pré-tragienne</span></li>\n          <li><span class=\"kw-clinique\">Hypoesthésie du lobe de l'oreille</span> (atteinte du nerf grand auriculaire)</li>\n          <li><span class=\"kw-clinique\">Fistule salivaire</span> si parotidectomie incomplète — régression spontanée habituelle</li>\n          <li><strong>Pas de diminution de la salive</strong> si parotidectomie isolée (<span class=\"kw-clinique\">les</span> autres glandes compensent)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Tumeur submandibulaire — risques opératoires propres.</strong>\n        <ul>\n          <li><span class=\"kw-ttt\">Exérèse</span> chirurgicale = règle, avec examen extemporané</li>\n          <li>Risque de <span class=\"kw-clinique\">lésion</span> de 3 nerfs : <span class=\"kw-clinique\">rameau marginal du nerf facial</span>, <span class=\"kw-clinique\">nerf lingual</span>, <span class=\"kw-clinique\">nerf hypoglosse</span></li>\n          <li>Évidement ganglionnaire cervical si malignité à l'extemporané</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Indication large à la <span class=\"kw-ttt\">chirurgie</span> parotidienne.</strong> Toute tumeur parotidienne doit en principe être enlevée pour examen histologique, étant donné la proportion non négligeable de tumeurs malignes (<span class=\"kw-chiffre\">20%</span>) — seuls <span class=\"kw-clinique\">les</span> très mauvais états généraux ou les Warthin quasi-certains relèvent de la <span class=\"kw-def\">surveillance</span>.\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/salivary-gland-tumours","label":"Radiopaedia : Salivary gland tumours"},{"href":"https://radiopaedia.org/articles/parotid-gland-tumors-1","label":"Radiopaedia : Parotid gland tumors"},{"href":"https://radiopaedia.org/articles/minor-salivary-gland-tumours","label":"Radiopaedia : Minor salivary gland tumours"}]},{"id":"90-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des biopsies des glandes salivaires accessoires","contenu":"<p>La <span class=\"kw-def\">biopsie des glandes salivaires accessoires (BGSA)</span> recherche une atteinte glandulaire dans 3 situations&nbsp;: suspicion de <strong><span class=\"kw-clinique\">syndrome de Gougerot</span>-<span class=\"kw-clinique\">Sjögren</span></strong>, d'<strong>amylose</strong> et de <strong><span class=\"kw-clinique\">sarcoïdose</span></strong>.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Condition de validité.</strong> Le prélèvement doit comprendre <span class=\"kw-chiffre\">≥ 4 glandes salivaires accessoires</span> pour être interprétable.\n      </div>\n\n      <h4 style=\"margin: 0.6em 0 0.3em; color: var(--ink);\"><span class=\"kw-clinique\">Gougerot-Sjögren</span> — <span class=\"kw-def\">classification</span> de Chisholm</h4>\n      <p>5 stades de gravité croissante (selon le degré de <span class=\"kw-ttt\">sclérose</span>) ; un <span class=\"kw-bio\">focus</span> = amas de <span class=\"kw-chiffre\">&gt; 50 lymphocytes</span> et/ou histiocytes pour <span class=\"kw-chiffre\">4 mm</span>².</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Stade</span> 0</strong> : absence de <span class=\"kw-bio\">lymphocyte</span> pour <span class=\"kw-chiffre\">4 mm</span>²</li>\n        <li><strong><span class=\"kw-def\">Stade</span> 1</strong> : infiltrat lymphoplasmocytaire léger</li>\n        <li><strong><span class=\"kw-def\">Stade</span> 2</strong> : infiltrat modéré, <span class=\"kw-chiffre\">&lt; 1 focus/4 mm²</span></li>\n        <li><strong><span class=\"kw-def\">Stade</span> 3</strong> : <span class=\"kw-chiffre\">1 focus/4 mm²</span> = barre diagnostique du <span class=\"kw-clinique\">Sjögren</span></li>\n        <li><strong><span class=\"kw-def\">Stade</span> 4</strong> : <span class=\"kw-chiffre\">&gt; 1 focus/4 mm²</span></li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> <strong>stades 3 et 4</strong> sont ceux rencontrés dans le <span class=\"kw-clinique\">syndrome de Gougerot</span>-<span class=\"kw-clinique\">Sjögren</span>.</p>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-clinique\">Sarcoïdose</span>.</strong> <span class=\"kw-bio\">Histologie</span>&nbsp;: granulome non nécrosant (tuberculoïde, sans <span class=\"kw-clinique\">nécrose</span> caséeuse) à cellules géantes et épithélioïdes. La BGSA n'est positive que dans <span class=\"kw-chiffre\">50%</span> des cas, mais une positivité évite un geste invasif (ex. <span class=\"kw-ttt\">biopsie</span> bronchique).\n      </div>","frequence":0},{"id":"90-11","rang":"B","rubrique":"Définition","titre":"Connaître les deux principaux types histologiques de tumeurs salivaires","contenu":"<h4 style=\"margin: 0.6em 0 0.3em; color: var(--ink);\">Tumeurs bénignes (≈<span class=\"kw-chiffre\"> 80%</span> des tumeurs principales)</h4>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Adénome pléomorphe</th><th>Cystadénolymphome (tumeur de Warthin)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Histologie</span></strong></td>\n            <td>Tumeur épithéliale avec cellules excrétrices + sécrétrices</td>\n            <td>Tumeur <strong>spécifique de la glande parotide</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Proportion</strong></td>\n            <td><span class=\"kw-chiffre\">70% des tumeurs parotidiennes</span> ;<span class=\"kw-chiffre\"> 80%</span> des tumeurs épithéliales bénignes</td>\n            <td><span class=\"kw-chiffre\">10% des tumeurs parotidiennes</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Tout âge, surtout adulte <span class=\"kw-chiffre\">30–60 ans</span></td>\n            <td>Homme <span class=\"kw-clinique\">fumeur</span> ++</td>\n          </tr>\n          <tr>\n            <td><strong>Présentation</strong></td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> unilatérale lentement progressive ; <span class=\"kw-clinique\">indolore, mobile, consistance variable</span> (dure / élastique / inhomogène) ; pas de symptôme, pas de PF, pas d'<span class=\"kw-clinique\">adénopathie</span></td>\n            <td>Tumeur d'allure <span class=\"kw-clinique\">kystique</span> ; <strong>à la pointe de la parotide</strong> ; <span class=\"kw-clinique\">bilatéralité 10%</span> ; clinique proche de l'adénome pléomorphe</td>\n          </tr>\n          <tr>\n            <td><strong>Risques</strong></td>\n            <td>Récidive &lt;<span class=\"kw-chiffre\"> 3%</span> ; transformation maligne rare → <strong><span class=\"kw-def\">surveillance</span> postopératoire annuelle prolongée</strong></td>\n            <td><strong>Pas de récidive</strong>, <strong>pas de dégénérescence</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Autres tumeurs bénignes plus rares.</strong>\n        <ul>\n          <li>Adénome <span class=\"kw-clinique\">monomorphe</span>/simple (<span class=\"kw-chiffre\">10–15%</span> des tumeurs des glandes salivaires principales)</li>\n          <li>Adénome <span class=\"kw-clinique\">oxyphile</span> / oncocytome</li>\n          <li>Adénome <span class=\"kw-clinique\">tubulaire</span> / trabéculaire</li>\n          <li>Adénome à cellules claires, adénome basocellulaire, papillome…</li>\n          <li>Tumeurs non épithéliales : <span class=\"kw-clinique\">lipome intraparotidien</span> ⭐ (distracteur classique), neurinome du facial, neurofibromes, hémangiome/lymphangiome kystique de l'enfant</li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin: 0.8em 0 0.3em; color: var(--ink);\">Tumeurs malignes (≈<span class=\"kw-chiffre\"> 20%</span> des tumeurs principales)</h4>\n\n      <table >\n        <thead>\n          <tr><th></th><th><span class=\"kw-clinique\">Carcinome</span> muco-épidermoïde</th><th>Carcinome adénoïde kystique (cylindrome)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Proportion</strong></td>\n            <td><span class=\"kw-chiffre\">10% des tumeurs parotidiennes</span> · <span class=\"kw-chiffre\">50% de toutes les tumeurs malignes salivaires</span></td>\n            <td><span class=\"kw-chiffre\">10% des tumeurs parotidiennes</span> · <span class=\"kw-chiffre\">10% des tumeurs malignes</span> · le plus fréquent dans <span class=\"kw-clinique\">les</span> glandes <strong>accessoires</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Tout âge, surtout <span class=\"kw-chiffre\">20–60 ans</span></td>\n            <td>Tout âge, surtout <span class=\"kw-chiffre\">40–50 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Sex-ratio</strong></td>\n            <td>Homme = Femme</td>\n            <td>Volontiers chez la <span class=\"kw-clinique\">femme</span></td>\n          </tr>\n          <tr>\n            <td><strong>Présentation</strong></td>\n            <td>Souvent <strong>d'allure bénigne</strong></td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> qui grossit lentement, puis aspect malin tardif (croissance rapide, tumeur dure inégale, douleurs, PFP, <span class=\"kw-clinique\">adénopathies</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> / risque</strong></td>\n            <td><span class=\"kw-def\">Grade</span> 1 (bas) → meilleur <span class=\"kw-def\">pronostic</span> ; <span class=\"kw-chiffre\">Grade 2</span> (intermédiaire) déjà malin ; Grade 3 (haut) mal limité avec <span class=\"kw-clinique\">adénopathies</span></td>\n            <td><span class=\"kw-alerte\">Récurrence locorégionale</span> + <span class=\"kw-alerte\">métastases tardives pulmonaires et osseuses</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Autres tumeurs malignes (rang C ORL).</strong>\n        <ul>\n          <li>Carcinomes à cellules acineuses (<span class=\"kw-chiffre\">10%</span> des malignes)</li>\n          <li>Adénocarcinomes (<span class=\"kw-chiffre\">20%</span> des malignes)</li>\n          <li>Carcinomes épidermoïdes et indifférenciés (<span class=\"kw-chiffre\">5%</span> des malignes)</li>\n          <li>Lymphome, sarcome, métastases ganglionnaires</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pseudo-tumeurs distracteurs.</strong> Certaines parotidites chroniques (parotidite syphilitique pseudotumorale, kystes canalaires) ⭐ peuvent simuler une tumeur — restent des distracteurs QCM classiques.\n      </div>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Périsialodochite (<span class=\"kw-clinique\">abcès</span> du plancher) :</strong> <span class=\"kw-ttt\">drainage chirurgical en urgence</span> ; l'<span class=\"kw-alerte\">intubation peut être rendue difficile par l'œdème buccal</span><br><strong>Risque évolutif :</strong> en l'absence de traitement, diffusion vers une <span class=\"kw-alerte\">médiastinite</span> ou une <span class=\"kw-alerte\">fistulisation cervicale</span><br><strong>Dogme oncologique :</strong> <span class=\"kw-alerte\">une douleur sur une tuméfaction salivaire = cancer jusqu'à preuve du contraire</span></p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-etio\">sialadénite virale</span> (<span class=\"kw-ttt\">traitement symptomatique</span>) et <span class=\"kw-etio\">lithiase</span> non compliquée (<span class=\"kw-ttt\">traitement médical</span> puis levée d'obstacle programmée)<br><strong>Avis chirurgical CMF/ORL :</strong> toute <span class=\"kw-etio\">tumeur salivaire</span> (<span class=\"kw-ttt\">parotidectomie avec examen extemporané</span>) et <span class=\"kw-etio\">sialadénose</span> (bilan d'une <span class=\"kw-etio\">pathologie générale</span>)<br><strong><span class=\"kw-alerte\">Urgence</span> chirurgicale :</strong> <span class=\"kw-alerte\">abcès du plancher / périsialodochite</span> → <span class=\"kw-ttt\">drainage</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Paralysie faciale périphérique</span> ou <span class=\"kw-alerte\">anesthésie du lobule de l'oreille</span> (nerf grand auriculaire) sur une <span class=\"kw-clinique\">tuméfaction</span> parotidienne</li><li><span class=\"kw-alerte\">Douleur</span> sur une <span class=\"kw-clinique\">tuméfaction</span> salivaire = <span class=\"kw-etio\">cancer jusqu'à preuve du contraire</span></li><li><span class=\"kw-alerte\">Fixité au plan profond ou cutané</span>, <span class=\"kw-clinique\">inflammation du revêtement cutané</span></li><li><span class=\"kw-alerte\">Adénopathie locorégionale</span> ou <span class=\"kw-alerte\">trismus</span></li><li><span class=\"kw-alerte\">Abcès du plancher buccal</span> : <span class=\"kw-clinique\">trismus</span>, <span class=\"kw-clinique\">dysphagie</span>, odynophagie (risque de <span class=\"kw-alerte\">médiastinite</span>)</li></ul>","principes":"<p>La PEC dépend du <span class=\"kw-etio\">type de pathologie</span> et, pour <span class=\"kw-clinique\">les</span> lithiases, de la <span class=\"kw-chiffre\">localisation</span> et de la <span class=\"kw-chiffre\">taille</span> du calcul par rapport au <span class=\"kw-clinique\">diamètre</span> du conduit.</p><p><strong>Épisode <span class=\"kw-etio\">inflammatoire</span> (sialadénite / lithiase)</strong></p><p>Puis traitement étiologique par <span class=\"kw-ttt\">levée de l'obstruction lithiasique</span> pour récupérer la fonction salivaire</p><ul><li><span class=\"kw-ttt\">Antibiothérapie spiramycine + métronidazole</span> pendant <span class=\"kw-chiffre\">≥ 10 jours</span></li><li><span class=\"kw-ttt\">Corticoïdes</span>, <span class=\"kw-ttt\">antalgiques</span> et <span class=\"kw-ttt\">réhydratation</span></li></ul><p><strong>Lithiase submandibulaire (conduit &lt;<span class=\"kw-chiffre\"> 4 mm</span>)</strong></p><ul><li>1/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> an</span>térieur (en avant de la 1ère molaire) : <span class=\"kw-ttt\">taille endobuccale sous anesthésie locale</span></li><li>1/3 moyen/postérieur, calcul <span class=\"kw-chiffre\">&lt; 4 mm</span> (mobile) : <span class=\"kw-ttt\">sialendoscopie</span></li><li>1/3 moyen/postérieur, calcul <span class=\"kw-chiffre\">&gt; 4 mm</span> (bloqué) : <span class=\"kw-ttt\">taille endobuccale</span></li></ul><p><strong>Lithiase parotidienne (conduit &lt;<span class=\"kw-chiffre\"> 2 mm</span>)</strong></p><p><span class=\"kw-ci\">Sialendoscopie contre-indiquée en cas de surinfection</span> (sialodochite, périsialodochite)</p><ul><li>1/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> an</span>térieur (en avant du bord antérieur du masséter) : <span class=\"kw-ttt\">taille endobuccale sous anesthésie générale</span> (risque de migration)</li><li>Calcul <span class=\"kw-chiffre\">≤ 2 mm</span> : <span class=\"kw-ttt\">sialendoscopie</span></li><li>Calcul <span class=\"kw-chiffre\">&gt; 3 mm</span> : <span class=\"kw-ttt\">lithotripsie ou laser</span> puis sialendoscopie ou abord par voie de lifting</li></ul><p><strong>Tumeur des glandes salivaires</strong></p><p><span class=\"kw-ttt\">Surveillance clinico-radiologique</span> seule si très mauvais état général ou tumeur de Warthin quasi-certaine</p><ul><li><span class=\"kw-ttt\">Parotidectomie avec examen extemporané</span> systématique si bon état général ou doute diagnostique</li><li><span class=\"kw-ttt\">Parotidectomie totale + évidement cervical homolatéral</span> si malignité à l'extemporané</li><li><span class=\"kw-ttt\">Radiothérapie adjuvante</span> si haut <span class=\"kw-def\">grade</span>, limites chirurgicales positives ou <span class=\"kw-bio\">envahissement</span> cutané/nerveux</li><li><span class=\"kw-ci\">Jamais de biopsie</span> (risque de <span class=\"kw-alerte\">lésion du nerf facial</span> et de dissémination)</li></ul><p><strong>Sialadénite <span class=\"kw-etio\">virale</span></strong></p><ul><li><span class=\"kw-ttt\">Traitement symptomatique</span> : repos, réhydratation, antipyrétique, <span class=\"kw-ttt\">antalgique</span></li><li><span class=\"kw-ttt\">Éviction scolaire 15 jours</span> (oreillons)</li></ul>","suivi":"<p><strong>Adénome pléomorphe :</strong> <span class=\"kw-ttt\">surveillance postopératoire annuelle prolongée</span> (risque de <span class=\"kw-etio\">récurrence</span> <span class=\"kw-chiffre\">&lt; 3 %</span> et de <span class=\"kw-etio\">transformation maligne</span>)<br><strong>Complications de la parotidectomie :</strong> <span class=\"kw-alerte\">paralysie faciale</span> (<span class=\"kw-chiffre\">20 %</span>), <span class=\"kw-etio\">syndrome de Frey</span> (<span class=\"kw-chiffre\">15 %</span>, tardif), hypoesthésie du lobe de l'oreille<br><strong>Sialadénite <span class=\"kw-etio\">virale</span> :</strong> guérison sans complication en <span class=\"kw-chiffre\">8-15 jours</span></p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/salivary-glands","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/parotid-gland","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/submandibular-gland","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/sialadenitis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/sialolithiasis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/sjogren-syndrome-1","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/salivary-gland-tumours","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/parotid-gland-tumors-1","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/minor-salivary-gland-tumours","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Tuméfaction d'une glande salivaire — Bilan clinique : caractère inflammatoire, latéralité, palper endobuccal","detail":"<h4>CAT — <span class=\"kw-clinique\">Tuméfaction</span> d'une glande salivaire — Orientation diagnostique et conduite à tenir</h4>","branches":[{"to":"q-inflammation","label":"Bilan clinique","color":"blue"}]},{"id":"q-inflammation","kind":"decision","label":"Signes inflammatoires (douleur + fièvre) ?","branches":[{"to":"q-gravite","label":"Oui (inflammatoire)","color":"red"},{"to":"q-aspect","label":"Non (froide, indolore)","color":"green"}]},{"id":"q-gravite","kind":"decision","label":"Signes d'abcès du plancher / diffusion cervicale ? — Tuméfaction du plancher, trismus, dysphagie, odynophagie","branches":[{"to":"t-urgence","label":"Oui","color":"red"},{"to":"q-laterality","label":"Non","color":"amber"}]},{"id":"t-urgence","kind":"terminal","label":"Drainage chirurgical en urgence","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Abcès du plancher buccal</span> : <span class=\"kw-clinique\">trismus</span>, <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">odynophagie</span> ± <span class=\"kw-clinique\">otalgie</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Drainage en urgence</span> + <span class=\"kw-ttt\">antibiothérapie</span></li><li><span class=\"kw-alerte\">Intubation difficile</span> par l'<span class=\"kw-clinique\">œdème</span> buccal ; risque de <span class=\"kw-alerte\">médiastinite</span></li></ul>"},{"id":"q-laterality","kind":"decision","label":"Atteinte uni- ou bilatérale ?","branches":[{"to":"t-virale","label":"Bilatérale","color":"green"},{"to":"q-echo","label":"Unilatérale","color":"amber"}]},{"id":"t-virale","kind":"terminal","label":"Sialadénite virale","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Tuméfaction parotidienne bilatérale fébrile</span>, <span class=\"kw-clinique\">sans pus à l'ostium</span> du canal de Sténon</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement symptomatique</span> + <span class=\"kw-ttt\">éviction scolaire 15 jours</span> (oreillons)</li></ul>"},{"id":"q-echo","kind":"decision","label":"Échographie : calcul visible ? — Examen de 1ère intention (calcul ≥ 2 mm)","branches":[{"to":"t-lithiase","label":"Calcul ≥ 2 mm","color":"amber"},{"to":"t-bacterienne","label":"Pas de calcul","color":"amber"}]},{"id":"t-lithiase","kind":"terminal","label":"Lithiase salivaire","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Hernie et colique salivaires rythmées par les repas</span> ; calcul au <span class=\"kw-clinique\">palper bidigital</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> en <span class=\"kw-chiffre\">1ère intention</span> (calcul <span class=\"kw-chiffre\">≥ 2 mm</span>) ± <span class=\"kw-imagerie\">TDM low dose</span> localisatrice</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement médical ≥ 10 j</span> puis <span class=\"kw-ttt\">levée d'obstacle</span> (sialendoscopie, taille endobuccale)</li></ul>"},{"id":"t-bacterienne","kind":"terminal","label":"Sialadénite bactérienne / sténose canalaire","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Tuméfaction inflammatoire avec issue de pus à l'ostium</span> (<span class=\"kw-etio\">staphylocoque doré</span>, <span class=\"kw-etio\">anaérobies</span>)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Sialo-IRM</span> si épisodes récidivants (recherche d'une <span class=\"kw-etio\">sténose canalaire</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Spiramycine + métronidazole</span> pendant <span class=\"kw-chiffre\">≥ 10 jours</span></li></ul>"},{"id":"q-aspect","kind":"decision","label":"Aspect de la tuméfaction non inflammatoire ?","branches":[{"to":"t-tumeur","label":"Nodule isolé","color":"amber"},{"to":"t-sialadenose","label":"Hypertrophie bilatérale indolore","color":"blue"}]},{"id":"t-tumeur","kind":"terminal","label":"Tumeur salivaire → parotidectomie","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Nodule isolé non inflammatoire</span> ; rechercher <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de malignité</span> (<span class=\"kw-clinique\">paralysie faciale</span>, douleur, fixité, <span class=\"kw-clinique\">adénopathie</span>)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM</span> (examen clé) + <span class=\"kw-imagerie\">cytoponction échoguidée</span> → diagnostic dans <span class=\"kw-chiffre\">90 %</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Parotidectomie avec examen extemporané</span> ; <span class=\"kw-ci\">jamais de biopsie</span></li></ul>"},{"id":"t-sialadenose","kind":"terminal","label":"Sialadénose (sialose)","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Parotidomégalie bilatérale chronique, indolore</span>, <span class=\"kw-clinique\">sans signe inflammatoire</span></li></ul><h4>Paraclinique</h4><ul><li>Bilan d'une <span class=\"kw-etio\">pathologie générale</span> ; <span class=\"kw-bio\">BGSA (≥ 4 glandes)</span> si suspicion de <span class=\"kw-etio\">syndrome de Gougerot-Sjögren</span></li></ul>"}]},"cards":[{"i":"07042f142f65","n":90,"o":"90-1","u":"Diagnostic positif","t":"Connaître la clinique des lithiases submandibulaire et parotidienne","q":"Quels sont les signes cliniques dominants d'une colique salivaire associée à une lithiase submandibulaire ?","a":"<p>Une colique salivaire due à une lithiase submandibulaire se caractérise par une <strong>douleur vive</strong>, également rythmée par les repas, survenant lors de la stimulation salivaire et soulagée par l'expulsion (même minime) de salive ou du calcul.</p>"},{"i":"1b2fff92bfe0","n":90,"o":"90-1","u":"Diagnostic positif","t":"Connaître la clinique des lithiases submandibulaire et parotidienne","q":"Comment se présente la douleur d'une sialodochite de Wharton (inflammation du canal de Wharton) dans le contexte d'une lithiase submandibulaire ?","a":"<p>La sialodochite de Wharton se manifeste par une <strong>douleur vive</strong>, souvent accompagnée de <strong>fièvre élevée</strong>, qui irradie vers l'oreille. Le patient peut également présenter une <strong>dysphagie</strong> et une <strong>hypersialorrhée</strong>. À l'inspection, une issue de pus peut être observée à l'ostium près du frein de la langue.</p>"},{"i":"2e346540a1b2","n":90,"o":"90-1","u":"Diagnostic positif","t":"Connaître la clinique des lithiases submandibulaire et parotidienne","q":"Quels sont les signes d'une sténonite (inflammation du canal de Sténon) au cours d'une lithiase parotidienne ?","a":"<p>Une sténonite d'origine lithiasique parotidienne se traduit par une <strong>inflammation jugale</strong> visible sur le trajet du conduit excréteur. Une issue de pus peut être constatée à l'ostium du canal de Sténon, face à la deuxième molaire supérieure.</p>"},{"i":"683bf83aa927","n":90,"o":"90-1","u":"Diagnostic positif","t":"Connaître la clinique des lithiases submandibulaire et parotidienne","q":"Quels sont les signes cliniques locaux et généraux d'une submandibulite (infection de la glande submandibulaire) secondaire à une lithiase submandibulaire ?","a":"<p>Une submandibulite se manifeste par une <strong>fièvre entre 38 et 39°C</strong>, une <strong>dysphagie</strong> et une <strong>otalgie</strong>. Une tuméfaction douloureuse de la glande submandibulaire est présente. Une issue de pus peut parfois être observée, et il existe un risque de fistulisation cervicale.</p>"},{"i":"73c1ffa84b20","n":90,"o":"90-1","u":"Diagnostic positif","t":"Connaître la clinique des lithiases submandibulaire et parotidienne","q":"Comment se présente à l'examen clinique l'inflammation d'une parotidite d'origine lithiasique ?","a":"<p>Une parotidite lithiasique se manifeste par une <strong>inflammation et une douleur en regard de la loge parotidienne</strong>, c'est-à-dire en arrière du ramus mandibulaire et sous l'oreille externe. La glande est tuméfiée et douloureuse à la palpation.</p>"},{"i":"7c2713393dca","n":90,"o":"90-1","u":"Diagnostic positif","t":"Connaître la clinique des lithiases submandibulaire et parotidienne","q":"Comment se manifeste cliniquement une hernie salivaire dans le cadre d'une lithiase submandibulaire ?","a":"<p>Dans le cadre d'une lithiase submandibulaire, une hernie salivaire se traduit par une <strong>tuméfaction de la région submandibulaire</strong>, rythmée par les repas, due à l'obstruction du canal de Wharton par le calcul.</p>"},{"i":"20677b54141a","n":90,"o":"90-3","u":"Diagnostic","t":"Savoir différencier les trois types de pathologie des glandes salivaires","q":"Quel critère clinique permet de distinguer une sialadénite d'une sialose ou d'une tumeur des glandes salivaires ?","a":"<p>La <strong>douleur</strong> est un critère important :</p><ul><li>La <strong>sialadénite</strong> est souvent douloureuse, parfois associée à de la fièvre.</li><li>La <strong>sialose</strong> est indolore, mais peut donner une sensation de pesanteur.</li><li>Une <strong>tumeur des glandes salivaires</strong> est généralement indolore. En présence d'une tuméfaction non inflammatoire, toute douleur doit faire suspecter un cancer jusqu'à preuve du contraire.</li></ul>"},{"i":"4b0755b58a4b","n":90,"o":"90-3","u":"Diagnostic","t":"Savoir différencier les trois types de pathologie des glandes salivaires","q":"Comment la latéralité de l'atteinte glandulaire aide-t-elle à distinguer les pathologies des glandes salivaires ?","a":"<ul><li>La <strong>sialadénite</strong> peut être uni- ou bilatérale.</li><li>La <strong>sialose</strong> est classiquement bilatérale (+ +).</li><li>La <strong>tumeur</strong> est le plus souvent unilatérale (+ +), bien que 10% des tumeurs de Warthin puissent être bilatérales.</li></ul>"},{"i":"99b846a6e9e8","n":90,"o":"90-3","u":"Diagnostic","t":"Savoir différencier les trois types de pathologie des glandes salivaires","q":"Quels sont les éléments clés du terrain à rechercher en cas de sialadenite, sialose ou tumeur des glandes salivaires ?","a":"<ul><li>Pour une <strong>sialadénite</strong>, rechercher une lithiase, une porte d'entrée canalaire, hématogène ou une cause virale.</li><li>Pour une <strong>sialose</strong>, rechercher une maladie générale (immunologique, nutritionnelle, endocrinienne) comme un syndrome de Gougerot-Sjögren, une IgG4 ou une sarcoïdose.</li><li>Pour une <strong>tumeur</strong>, elle survient souvent chez l'adulte de 30-60 ans, touchant préférentiellement la parotide.</li></ul>"},{"i":"9caa86642af6","n":90,"o":"90-3","u":"Diagnostic","t":"Savoir différencier les trois types de pathologie des glandes salivaires","q":"Comment différencier une pathologie inflammatoire des glandes salivaires (sialadénite) d'une sialose ou d'une tumeur ?","a":"<p>La présence d'une <strong>inflammation</strong> est le premier critère de différenciation. Une sialadénite présente des signes inflammatoires, contrairement à une sialose ou une tumeur.</p>"},{"i":"dbe75f8472ad","n":90,"o":"90-3","u":"Diagnostic","t":"Savoir différencier les trois types de pathologie des glandes salivaires","q":"Quelle est la particularité clinique d'une sialadénite, en dehors de la douleur et de l'inflammation ?","a":"<p>Lors d'une sialadénite, la glande est inflammée et il peut y avoir du <strong>pus à l'ostium</strong> du canal excréteur.</p>"},{"i":"2263ef95a35b","n":90,"o":"90-5","u":"Contenu multimédia","t":"Iconographie clinique d’un exemple typique de tuméfaction parotidienne","q":"Quels sont les éléments sémiologiques clés à évaluer lors de l'examen clinique d'une tuméfaction parotidienne ?","a":"<ul><li><strong>Localisation précise</strong> : parotidienne superficielle ou profonde.</li><li><strong>Taille et forme</strong> : évaluer les dimensions et la morphologie.</li><li><strong>Consistance</strong> : molle, élastique, dure, fluctuante.</li><li><strong>Mobilité</strong> : par rapport aux plans superficiels et profonds.</li><li><strong>Douleur</strong> : spontanée ou à la palpation.</li><li><strong>Signes inflammatoires associés</strong> : rougeur, chaleur, œdème cutané.</li><li><strong>Parésie/paralysie faciale</strong> : signe d'atteinte du nerf facial (orientant vers une tumeur maligne).</li><li><strong>Adénopathies cervicales associées</strong>.</li><li><strong>Examen du canal de Sténon</strong> : flux salivaire, présence de pus ou de calcul.</li></ul>"},{"i":"24889e9a5104","n":90,"o":"90-5","u":"Contenu multimédia","t":"Iconographie clinique d’un exemple typique de tuméfaction parotidienne","q":"Quelles peuvent être les principales étiologies d'une tuméfaction parotidienne unilatérale ?","a":"<ul><li><strong>Infectieuses</strong> : parotidite virale (oreillons), bactérienne (staphylocoque), abcès.</li><li><strong>Inflammatoires</strong> : pseudo-tumeur liée à une maladie auto-immune (ex: Gougerot-Sjögren), sarcoïdose.</li><li><strong>Tumorales bénignes</strong> : <strong>adénome pléomorphe</strong> (tumeur la plus fréquente), tumeur de Warthin.</li><li><strong>Tumorales malignes</strong> : <strong>carcinome muco-épidermoïde</strong>, carcinome adénoïde kystique, adénocarcinome, carcinome à cellules acineuses, lymphome.</li><li><strong>Lithiasiques</strong> : calcul du canal de Sténon (rare dans la parotide).</li><li><strong>Kystiques</strong> : kyste de la première fente branchiale.</li></ul>"},{"i":"73b2b0ea59e4","n":90,"o":"90-5","u":"Contenu multimédia","t":"Iconographie clinique d’un exemple typique de tuméfaction parotidienne","q":"Comment définir cliniquement une tuméfaction parotidienne typique ?","a":"<p>Une tuméfaction parotidienne typique se présente cliniquement comme une <strong>masse</strong> palpable, le plus souvent <strong>unilatérale</strong>, située en arrière et au-dessous de l'angle de la mandibule, pouvant déformer la région pré-auriculaire et s'étendre vers le cou. Sa consistance, sa mobilité et sa douleur sont variables selon l'étiologie.</p>"}]};